<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\DelegateLogin\Infrastructure\Provider;

use Override;
use Throwable;
use GuzzleHttp\Client;
use GuzzleHttp\ClientInterface;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedUserData;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedLoginEndpoint;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedLoginProvider;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedProviderDescription;

/**
 * DelegatedLoginProvider implementation for Sign in with Apple (OAuth 2.0 / OIDC with ES256 client secret).
 *
 * Apple's authorization flow differs from standard OAuth in several ways: the client secret
 * is a short-lived JWT signed with an EC private key using the ES256 algorithm, the token
 * endpoint always returns an id_token (OIDC), and user profile data is only provided on the
 * very first authorization. This class generates the client-secret JWT on each token exchange,
 * verifies the nonce embedded in the id_token to prevent replay attacks, and maps the Apple
 * claims to the normalized DelegatedUserData structure expected by the rest of the system.
 * The authorization endpoint uses the form_post response mode as required by Apple.
 */
class AppleOAuthProvider implements DelegatedLoginProvider
{
    private const AUTH_URL = 'https://appleid.apple.com/auth/authorize';
    private const TOKEN_URL = 'https://appleid.apple.com/auth/token';
    private readonly string $assetsPath;

    public function __construct(
        AppConfig $config,
        Context $context,
        private readonly string $id,
        private readonly string $clientId,
        private readonly string $teamId,
        private readonly string $keyId,
        private readonly string $privateKeyPem,
        private readonly ClientInterface $http = new Client()
    ) {
        $this->assetsPath = $config->get('oidc.assets.path', $context->getBaseUrl() . '/oauth/assets/');
    }

    /**
     * Returns the display metadata for the Apple provider including the logo asset path
     * so the login page can render the "Sign in with Apple" button.
     */
    #[Override]
    public function info(): DelegatedProviderDescription
    {
        return new DelegatedProviderDescription(
            id: $this->id,
            name: 'Apple',
            logo: $this->assetsPath . '/socials/apple.png'
        );
    }

    /**
     * Builds the Apple authorization URL using the form_post response mode required by Apple,
     * embedding a SHA-256 nonce derived from the state to allow replay protection on callback.
     */
    #[Override]
    public function delegeatedUrl(string $redirect, string $state): DelegatedLoginEndpoint
    {
        $nonce = hash('sha256', $state);
        $url = self::AUTH_URL . '?' . http_build_query([
            'client_id' => $this->clientId,
            'redirect_uri' => $redirect,
            'response_type' => 'code id_token',
            'response_mode' => 'form_post',
            'scope' => 'name email',
            'state' => $state,
            'nonce' => $nonce,
        ]);
        return new DelegatedLoginEndpoint('GET', $url);
    }

    /**
     * Exchanges the authorization code for an id_token at the Apple token endpoint, verifies the
     * nonce claim, extracts user profile data from the id_token claims and the optional user JSON
     * payload present only on the first authorization, then returns normalized DelegatedUserData.
     */
    #[Override]
    public function authorize(string $redirect, array $request): ?DelegatedUserData
    {
        try {
            $code = (string) ($request['code'] ?? '');
            if ($code === '') {
                return null;
            }

            $clientSecret = $this->generateClientSecret();
            $response = $this->http->request('POST', self::TOKEN_URL, [
                'form_params' => [
                    'grant_type' => 'authorization_code',
                    'code' => $code,
                    'redirect_uri' => $redirect,
                    'client_id' => $this->clientId,
                    'client_secret' => $clientSecret,
                ],
                'headers' => ['Accept' => 'application/json'],
            ]);

            $tokenData = json_decode((string) $response->getBody(), true);
            $idToken = (string) ($tokenData['id_token'] ?? '');
            if ($idToken === '') {
                return null;
            }
            $claims = $this->parseJwtPayload($idToken);
            if (!is_array($claims)) {
                return null;
            }

            $state = (string) ($request['state'] ?? '');
            $expectedNonce = $state === '' ? null : hash('sha256', $state);
            $tokenNonce = isset($claims['nonce']) ? (string) $claims['nonce'] : null;
            if ($expectedNonce !== null && $tokenNonce !== null && $expectedNonce !== $tokenNonce) {
                return null;
            }

            $email = (string) ($claims['email'] ?? '');
            if ($email === '') {
                return null;
            }

            $userPayload = [];
            $rawUser = $request['user'] ?? null;
            if (is_string($rawUser) && $rawUser !== '') {
                $decodedUser = json_decode($rawUser, true);
                if (is_array($decodedUser)) {
                    $userPayload = $decodedUser;
                }
            }

            $name = null;
            $givenName = null;
            $familyName = null;
            if (isset($userPayload['name']) && is_array($userPayload['name'])) {
                $givenName = isset($userPayload['name']['firstName']) ? (string) $userPayload['name']['firstName'] : null;
                $familyName = isset($userPayload['name']['lastName']) ? (string) $userPayload['name']['lastName'] : null;
                $composed = trim(($givenName ?? '') . ' ' . ($familyName ?? ''));
                $name = $composed !== '' ? $composed : null;
            }

            return new DelegatedUserData(
                providerUserId: (string) ($claims['sub'] ?? ''),
                email: $email,
                name: $name,
                givenName: $givenName,
                familyName: $familyName,
                emailVerified: ((bool) ($claims['email_verified'] ?? false))
            );
        } catch (Throwable $ex) {
            return null;
        }
    }

    private function generateClientSecret(): string
    {
        $header = ['alg' => 'ES256', 'kid' => $this->keyId, 'typ' => 'JWT'];
        $now = time();
        $payload = [
            'iss' => $this->teamId,
            'iat' => $now,
            'exp' => $now + 15777000,
            'aud' => 'https://appleid.apple.com',
            'sub' => $this->clientId,
        ];

        $headerEncoded = $this->base64UrlEncode((string) json_encode($header));
        $payloadEncoded = $this->base64UrlEncode((string) json_encode($payload));
        $data = $headerEncoded . '.' . $payloadEncoded;

        $privateKey = openssl_pkey_get_private($this->privateKeyPem);
        if ($privateKey === false) {
            throw new \RuntimeException('Invalid Apple private key');
        }

        $signature = '';
        $signed = openssl_sign($data, $signature, $privateKey, OPENSSL_ALGO_SHA256);
        if ($signed === false) {
            throw new \RuntimeException('Unable to sign Apple client secret');
        }

        return $data . '.' . $this->base64UrlEncode($this->derToJose($signature, 64));
    }

    private function parseJwtPayload(string $token): ?array
    {
        $parts = explode('.', $token);
        if (count($parts) !== 3) {
            return null;
        }
        $decoded = $this->base64UrlDecode($parts[1]);
        if ($decoded === null) {
            return null;
        }
        $payload = json_decode($decoded, true);
        return is_array($payload) ? $payload : null;
    }

    private function base64UrlEncode(string $value): string
    {
        return rtrim(strtr(base64_encode($value), '+/', '-_'), '=');
    }

    private function base64UrlDecode(string $value): ?string
    {
        $remainder = strlen($value) % 4;
        if ($remainder > 0) {
            $value .= str_repeat('=', 4 - $remainder);
        }
        $decoded = base64_decode(strtr($value, '-_', '+/'), true);
        return $decoded === false ? null : $decoded;
    }

    private function derToJose(string $der, int $partLength): string
    {
        $offset = 3;
        $rLength = ord($der[$offset]);
        $offset += 1;
        $r = substr($der, $offset, $rLength);
        $offset += $rLength + 1;
        $sLength = ord($der[$offset - 1]);
        $s = substr($der, $offset, $sLength);

        $r = ltrim($r, "\x00");
        $s = ltrim($s, "\x00");
        $r = str_pad($r, intdiv($partLength, 2), "\x00", STR_PAD_LEFT);
        $s = str_pad($s, intdiv($partLength, 2), "\x00", STR_PAD_LEFT);

        return $r . $s;
    }
}
